(function(W){W.SCI_CH=W.SCI_CH||{};W.SCI_CH["f3-2"]={"sec":[{"h":"Water and Germination","ul":["The embryo inside a seed needs three necessary conditions to begin germinating and growing into a new plant. They are: 1. Water. 2. Air. 3. A suitable temperature (warmth).","To study the effect of the three conditions on germination: you must follow an important scientific rule called \"Comparing under the same conditions\"."]},{"h":"Comparing under the same conditions","def":["Comparing under the same conditions","It is an important scientific rule in which the effect of one condition is studied by changing only the condition you are studying (condition to change) with keeping all the other conditions the same (conditions to keep the same)."]},{"h":"What happens?","p":["If two conditions are changed at the same time while studying the effect of one condition in a scientific experiment? We will not know which one was the true cause of the result obtained from the experiment."]},{"h":"Activity: Do Seeds Need Water to Germinate?","p":["The importance of each of the three necessary conditions for germination can be determined by carrying out simple practical experiments. When studying the importance of water for germination:"],"ul":["Condition to change: presence or absence of water.","Conditions to keep the same: temperature, presence of air, light.","Materials and tools: kidney bean seeds, pieces of cotton, transparent plastic cups, water."]},{"h":"Steps","steps":["Bring the two plastic cups and label the first cup (A) moistened with water, and the second cup (B) dry.","Put an equal amount of cotton in the bottom of each cup, then place an equal number of kidney bean seeds in each cup.","Moisten the cotton in cup (A) with a suitable amount of water, and leave cup (B) dry without adding water.","Place both cups in a warm place so that the temperature and light are the same for both cups.","Observe the seeds daily for several days and record your observations."],"note":["Caution:","Do not add so much water that the seeds become completely submerged. Because seeds need air to breathe during germination."]},{"h":"Observation","tbl":{"head":["Cup","Condition to change","Conditions to keep the same","Result after several days"],"rows":[["Cup (A)","Presence of water","Presence of air, temperature, light","The seeds germinate."],["Cup (B)","Absence of water","Presence of air, temperature, light","The seeds did not germinate."]]}},{"h":"Conclusion","ul":["Seeds need water to begin germination."]}],"vocab":[["necessary","ضروري"],["experiment","تجربة"],["scientific rule","قاعدة علمية"],["true","حقيقي"],["result","نتيجة"],["practical","عملي"],["transparent","شفاف"],["moisten","يرطب"],["equal","متساوية"],["leave","يترك"],["absence","غياب"],["pieces","قطع"],["dry","جاف"],["amount","كمية"],["warm","دافئ"],["begin","يبدأ"],["breathe","يتنفس"],["submerge","يغمر"]],"q":[["How many necessary conditions does the embryo need to begin germinating?",["Three","Four","Two"],0],["Which is one of the three necessary conditions for germination?",["Water","Soil only","Sunlight only"],0],["Which three conditions are necessary for germination?",["Water, soil and light","Water, air and a suitable temperature","Light, soil and fertilizer"],1],["The important scientific rule used to study the effect of the three conditions is called ______.",["Changing all conditions","Guessing the result","Comparing under the same conditions"],2],["In \"Comparing under the same conditions\", how many conditions do you change?",["Only one condition","Two conditions","All conditions"],0],["In this rule, the other conditions are kept ______.",["hidden","the same","different"],1],["The condition you are studying is called the condition to ______.",["keep the same","remove","change"],2],["What happens if two conditions are changed at the same time?",["We will not know which one was the true cause of the result","The seeds grow faster","The experiment is more correct"],0],["In the water experiment, the condition to change is ______.",["light","presence or absence of water","temperature"],1],["Which condition is kept the same in the water experiment?",["Presence of water","Absence of water","Temperature"],2],["Which materials are used in the water experiment?",["Kidney bean seeds, cotton, plastic cups, water","Iodine solution and a dropper","A refrigerator and a cardboard box"],0],["In the water experiment, cup (A) is ______.",["put in the refrigerator","moistened with water","dry"],1],["In the water experiment, cup (B) is ______.",["dry","submerged in water","moistened with water"],0],["In the water experiment, where are the two cups placed?",["In a warm place so temperature and light are the same","One in the refrigerator","Under water"],0],["What is put in the bottom of each cup?",["Sand","An equal amount of cotton","Different amounts of cotton"],1],["Why should you not add so much water that the seeds are completely submerged?",["Because the cotton will melt","Because water is cold","Because seeds need air to breathe during germination"],2],["What happens to the seeds in cup (A) after several days?",["The seeds germinate","The seeds did not germinate","The seeds dry out"],0],["What happens to the seeds in cup (B) after several days?",["The seeds turn blue","The seeds germinate","The seeds did not germinate"],2],["What is the conclusion of the water experiment?",["Seeds do not need water","Seeds need only light","Seeds need water to begin germination"],2],["How should you observe the seeds?",["Daily for several days","Only once","Never"],0]]};W.SCI_CH["f3-3"]={"sec":[{"h":"Air and Germination","p":["Seeds need air to germinate, just as humans need air to live. Now, we will study air as considered one of the three necessary conditions."]},{"h":"Activity: Do Seeds Need Air to Germinate?","p":["When studying the importance of air for germination:"],"ul":["Condition to change: exposed or not exposed to air.","Conditions to keep the same: temperature, presence of water, light.","Materials and tools: kidney bean seeds, plastic cups and pieces of cotton."]},{"h":"Steps","steps":["Bring the two plastic cups and label the first cup (A) exposed to air, and the second cup (B) not exposed to air.","Put some cotton in cup (A) and moisten it with a suitable amount of water, and place some kidney bean seeds on it so that the seeds are exposed to air.","Put the same number of seeds in cup (B), then pour water until the seeds are completely submerged below the water surface so that the seeds are not exposed to air.","Place both cups in a warm place so that the temperature and light are the same for both cups.","Observe the seeds daily for several days and record your observations."]},{"h":"Observation","tbl":{"head":["Cup","Condition to change","Conditions to keep the same","Result after several days"],"rows":[["Cup (A)","Exposed to air","Presence of water, temperature, light","The seeds germinate."],["Cup (B)","Not exposed to air","Presence of water, temperature, light","The seeds did not germinate."]]}},{"h":"Conclusion","ul":["Seeds need air to begin germination."]}],"vocab":[["expose to","يتعرض إلى"],["pour","يصب"],["below","أسفل"],["submerge","يغمر"]],"q":[["Seeds need air to germinate, just as humans need air to ______.",["sing","live","sleep"],1],["In the air experiment, the condition to change is ______.",["temperature","light","exposed or not exposed to air"],2],["Which conditions are kept the same in the air experiment?",["Temperature, presence of water, light","Presence of air only","Type of seeds only"],0],["Which materials are used in the air experiment?",["A refrigerator and a box","Kidney bean seeds, plastic cups and pieces of cotton","Iodine solution and a dropper"],1],["In the air experiment, cup (A) is ______.",["not exposed to air","put in the refrigerator","exposed to air"],2],["In the air experiment, cup (B) is ______.",["exposed to air","not exposed to air","dry"],1],["What is put in cup (A)?",["Dry cotton","Cotton moistened with a suitable amount of water and seeds on it","Seeds under water only"],1],["What is done in cup (B) so the seeds are not exposed to air?",["The cup is covered with a box","The cup is left dry","Water is poured until the seeds are completely submerged"],2],["The same number of seeds is put in cup (B) as in cup (A). Why?",["To compare under the same conditions","To make cup (B) heavier","It does not matter"],0],["Where are both cups placed?",["Both in the dark cold place","In a warm place so temperature and light are the same","One in the refrigerator"],1],["What happens to the seeds in cup (A) after several days?",["The seeds did not germinate","The seeds melt","The seeds germinate"],2],["What happens to the seeds submerged in water in cup (B)?",["The seeds germinate","The seeds did not germinate","The seeds turn into plants quickly"],1],["Why did the seeds in cup (B) not germinate?",["There was no light","They were not exposed to air","The water was cold"],1],["What is the conclusion of the air experiment?",["Seeds do not need air","Seeds need only water","Seeds need air to begin germination"],2],["Which condition must NOT change between the cups in the air experiment?",["Temperature","Exposure to air","Nothing"],0],["How many conditions do we change in this experiment?",["Three","One","Two"],1]]};W.SCI_CH["f3-4"]={"sec":[{"h":"Temperature and Germination","p":["A suitable temperature (warmth) is one of the necessary conditions for seeds to germinate."]},{"h":"Activity: Does Temperature Affect Seed Germination?","p":["When studying the importance of temperature for germination:"],"ul":["Condition to change: temperature.","Conditions to keep the same: presence of air, presence of water, light.","Materials and tools: kidney bean seeds, transparent plastic cups, water, refrigerator, cardboard box, small wooden blocks."]},{"h":"Steps","steps":["Bring the two plastic cups and label the first cup (A) warm environment, and the second cup (B) cold environment.","Put an equal amount of cotton in each cup and moisten it with a suitable and equal amount of water.","Place an equal number of kidney bean seeds on the cotton in each cup.","Place cup (A) in a warm place and cover it with a cardboard box. Then place small wooden blocks under the edges of the box to allow air to enter.","Place cup (B) inside the refrigerator.","Observe the seeds daily for several days and record your observations."],"note":["Take care:","The cup is placed inside a cardboard box to keep the light conditions the same as the refrigerator. The cup is placed inside the refrigerator to provide a cold environment that is unsuitable for seed germination."]},{"h":"Observation","tbl":{"head":["Cup","Condition to change","Conditions to keep the same","Result after several days"],"rows":[["Cup (A)","Suitable temperature (warmth)","Presence of water, presence of air","The seeds germinate."],["Cup (B)","Not suitable temperature (cold)","Presence of water, presence of air","The seeds did not germinate."]]}},{"h":"Conclusion","ul":["Seeds need a suitable temperature (warmth) to begin germination."]},{"h":"From the previous, we can conclude that","ul":["Water, air, and a suitable temperature are necessary conditions for seed germination. If any one of these three conditions is absent, the seeds will not germinate."]}],"vocab":[["refrigerator","ثلاجة"],["environment","بيئة"],["wooden blocks","مكعبات خشبية"],["cardboard","كرتون"],["cover","يغطي"],["allow","يسمح"],["unsuitable","غير مناسب"],["edges","حواف"],["enter","يدخل"]],"q":[["A suitable temperature (warmth) is one of the ______ conditions for germination.",["unneeded","harmful","necessary"],2],["In the temperature experiment, the condition to change is ______.",["temperature","presence of water","presence of air"],0],["Which conditions are kept the same in the temperature experiment?",["Type of cup only","Presence of air, presence of water, light","Temperature only"],1],["Which tool is used to provide a cold environment?",["Cardboard box","Wooden blocks","Refrigerator"],2],["Cup (A) is placed in a ______ environment.",["warm","cold","dry"],0],["Cup (B) is placed ______.",["under a box in a warm room","inside the refrigerator","in the sun"],1],["Why is cup (A) covered with a cardboard box?",["To make the temperature higher","To stop air from entering","To keep the light conditions the same as the refrigerator"],2],["Why are small wooden blocks placed under the edges of the box?",["To allow air to enter","To make the box taller for fun","To keep the seeds dry"],0],["Why is cup (B) placed inside the refrigerator?",["To keep the air out","To provide a cold environment that is unsuitable for seed germination","To make the seeds germinate faster"],1],["An equal amount of cotton is put in each cup and moistened with ______ of water.",["different amounts","a large amount to cover the seeds","a suitable and equal amount"],2],["What happens to the seeds in cup (A)?",["The seeds germinate","The seeds did not germinate","The seeds turn blue"],0],["What happens to the seeds in cup (B)?",["The seeds grow faster","The seeds germinate","The seeds did not germinate"],2],["What is the conclusion of the temperature experiment?",["Seeds do not need warmth","Seeds need only light","Seeds need a suitable temperature (warmth) to begin germination"],2],["Which are the necessary conditions for seed germination?",["Water, air, and a suitable temperature","Light, soil, and fertilizer","Water only"],0],["If one of the three necessary conditions is absent, the seeds will ______.",["germinate normally","not germinate","germinate quickly"],1],["How should you observe the seeds?",["Only on the first day","After one year","Daily for several days"],2]]};W.SCI_CH["f3-s"]={"sec":[{"h":"Structure of a kidney bean seed","ul":["The seed coat.","The embryo: a small part that looks like a small plant. It develops into roots, stems and leaves to form a new plant.","The two cotyledons: the largest part of the seed. They act as a store of food (starch) needed by the embryo at the beginning of growth."]},{"h":"Testing for the presence of starch","ul":["Test for the presence of starch in the cotyledons using iodine solution.","Iodine solution turns dark blue in the presence of starch."]},{"h":"Germination","p":["It is the process in which a small plant sprouts from the seed and begins to grow."]},{"h":"Conditions for germination","ul":["Water.","Air.","The temperature is suitable."]},{"h":"The rule","p":["When carrying out the required experiments to verify the effect of each germination condition, the \"comparing under the same conditions\" rule must be applied by: changing only one condition (the condition to change) and keeping all the other conditions the same."]}],"vocab":[],"q":[["Which part of the seed is a small part that looks like a small plant?",["The embryo","The seed coat","The cotyledons"],0],["The embryo develops into ______.",["the cotyledons","roots, stems and leaves","the seed coat"],1],["Which is the largest part of the seed?",["The embryo","The seed coat","The two cotyledons"],2],["The cotyledons act as a store of ______ needed by the embryo.",["food (starch)","water only","air"],0],["Which solution is used to test for starch?",["Sugar solution","Iodine solution","Salt solution"],1],["Iodine solution turns ______ in the presence of starch.",["red","colorless","dark blue"],2],["The process in which a small plant sprouts from the seed and begins to grow is ______.",["germination","pollination","hibernation"],0],["Which is a condition for germination?",["Magnifying glass","Water","Fertilizer"],1],["Which is another condition for germination?",["Wind only","Rocks","Air"],2],["Which is the third condition for germination?",["A suitable temperature","A very cold place","Darkness only"],0],["To study the effect of each condition, which scientific rule is applied?",["Copying","Comparing under the same conditions","Changing all conditions"],1],["The rule means changing ______ condition and keeping all the other conditions the same.",["two","all","only one"],2],["If one of the three conditions is missing, the seeds will ______.",["not germinate","germinate","turn blue"],0],["What do we call the condition we change in an experiment?",["The conclusion","The condition to change","The result"],1]]};W.SCI_CH["f3-q"]={"qonly":1,"sec":[],"vocab":[],"q":[["A kidney bean seed consists of ______ parts.",["three","four","two"],0],["Which part of the kidney bean seed grows to form a new plant?",["The embryo","The seed coat","The iodine"],0],["The cotyledons act as a ______.",["root","store of food","cover"],1],["Which nutrient is stored in the cotyledons?",["Iodine","Sugar water","Starch"],2],["What color does iodine solution become when applied to starch?",["Dark blue","Green","Red"],0],["What is the original color of iodine solution?",["White","Brown","Dark blue"],1],["The embryo needs ______ necessary conditions to begin germinating.",["three","five","two"],0],["Which is NOT a necessary condition for germination?",["Fertilizer","Water","Air"],0],["In the water experiment, the condition to change is ______.",["light","presence or absence of water","temperature"],1],["In the air experiment, the condition to change is ______.",["presence of water","light","exposed or not exposed to air"],2],["In the temperature experiment, the condition to change is ______.",["temperature","presence of water","presence of air"],0],["Seeds in the dry cup (B) of the water experiment ______.",["turned blue","did not germinate","germinated"],1],["Seeds submerged in water did not germinate because they were not exposed to ______.",["sunlight","cotton","air"],2],["Seeds in the refrigerator did not germinate because the ______ was too low.",["temperature","water","air"],0],["Why is a cardboard box placed over the warm cup in the temperature experiment?",["To prevent air from entering","To keep the light conditions the same as the refrigerator","To make the temperature higher"],1],["Why are wooden blocks placed under the box?",["To stop light","To keep the cup cold","To allow air to enter"],2],["Why do we not add too much water in the water experiment?",["Seeds need air to breathe during germination","Water is expensive","The cup would be cold"],0],["If two conditions are changed at the same time, we ______.",["can germinate faster","will not know the true cause of the result","will get a better result"],1],["Seeds placed on moistened cotton in the refrigerator will ______.",["germinate","turn blue","not germinate"],2],["Seeds placed on moistened cotton in a completely dark box in a warm room will ______.",["germinate, because water, air and warmth are present","not germinate","dry out"],0],["Which statement is correct about germination conditions?",["Air is not needed","If one of the three conditions is missing, seeds will not germinate","Water alone is enough"],1],["What do you learn from the experiment about air?",["Seeds do not need air","Seeds need only warmth","Seeds need air to begin germination"],2],["The seed coat is easier to remove after soaking the seed in water ______.",["overnight","for one second","in a refrigerator"],0],["The sunflower seed is dark gray with long white ______.",["spots","stripes","dots"],1]]};})(window);
